import type { Game } from "./common";
import itchData from "./itch.json";

// Generated by scripts/fetch-itch.mjs (runs before `npm run dev` / `npm run build`)
type ItchInfo = {
  coverUrl?: string;
  iconUrl?: string;
  screenshots?: string[];
};
const itch = itchData as Record<string, ItchInfo>;

// itch's full-size cover replaces the manual image; Steam's (applied after) still wins
export function withItch(game: Game): Game {
  const info = game.store.itch ? itch[game.store.itch] : undefined;
  if (!info) return game;
  return {
    ...game,
    imageUrl: info.coverUrl ?? game.imageUrl,
    iconUrl: info.iconUrl,
    screenshots: info.screenshots,
  };
}
